<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user=requireLogin();require_once BASE_PATH.'/includes/rental-operations-common.php';ro_require_permission('payments.manage');$pdo=Database::connection();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT p.*,i.invoice_number,i.currency,i.total_amount,c.first_name,c.last_name,c.phone,c.email,u.first_name AS staff_first,u.last_name AS staff_last FROM payments p JOIN invoices i ON i.invoice_id=p.invoice_id JOIN customers c ON c.customer_id=i.customer_id LEFT JOIN users u ON u.user_id=p.received_by WHERE p.payment_id=?');$stmt->execute([$id]);$p=$stmt->fetch(PDO::FETCH_ASSOC);if(!$p){http_response_code(404);exit('Receipt not found.');}$stmt=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM payment_refunds WHERE payment_id=? AND status='processed'");$stmt->execute([$id]);$refunded=(float)$stmt->fetchColumn();$pageTitle='Receipt '.$p['payment_number'];$currentPage='payments';require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/rental-operations-nav.php';
?>
<div class="ro-shell ro-receipt-shell"><div class="ro-page-heading no-print"><div><a class="ro-back-link" href="<?= e(base_url('admin/invoice-view.php?id='.(int)$p['invoice_id'])) ?>"><i class="bi bi-arrow-left"></i> Back to invoice</a><h1>Payment receipt</h1><p>Print or save this receipt for the customer.</p></div><button class="btn ro-btn-outline" onclick="window.print()" type="button"><i class="bi bi-printer me-1"></i> Print receipt</button></div><article class="ro-receipt"><div class="ro-receipt-banner"><div class="ro-brand-mark"><i class="bi bi-car-front-fill"></i></div><div><span class="ro-kicker">PAYMENT RECEIPT</span><h2><?= e((string)setting('business_name','Car Rental Business')) ?></h2><p>Official record of payment received</p></div><div class="ro-receipt-check"><i class="bi bi-check-circle-fill"></i><span><?= e(ucwords(str_replace('_',' ',$p['status']))) ?></span></div></div><div class="ro-receipt-amount"><span>AMOUNT RECEIVED</span><strong><?= ro_money($p['amount'],$p['currency']) ?></strong><small><?= e(ro_date($p['payment_date'])) ?></small></div><div class="ro-receipt-details"><div><span>Receipt number</span><strong><?= e($p['payment_number']) ?></strong></div><div><span>Invoice number</span><strong><?= e($p['invoice_number']) ?></strong></div><div><span>Customer</span><strong><?= e($p['first_name'].' '.$p['last_name']) ?></strong></div><div><span>Contact</span><strong><?= e($p['phone']) ?><?= $p['email']?' · '.e($p['email']):'' ?></strong></div><div><span>Payment method</span><strong><?= e(ucwords(str_replace('_',' ',$p['payment_method']))) ?></strong></div><div><span>Transaction reference</span><strong><?= e($p['transaction_reference']?:'Not supplied') ?></strong></div><div><span>Provider</span><strong><?= e($p['provider_name']?:'—') ?></strong></div><div><span>Received by</span><strong><?= e(trim(($p['staff_first']??'').' '.($p['staff_last']??''))?:'System') ?></strong></div><div><span>Processed refunds</span><strong><?= ro_money($refunded,$p['currency']) ?></strong></div><div><span>Net retained from this payment</span><strong><?= ro_money(max(0,(float)$p['amount']-$refunded),$p['currency']) ?></strong></div></div><?php if($p['notes']): ?><div class="ro-receipt-notes"><span>Notes</span><p><?= e($p['notes']) ?></p></div><?php endif; ?><footer>Thank you for your business. Please keep this receipt for your records.<br><small>This receipt confirms a database record. Payment-provider settlement should be verified separately.</small></footer></article></div>
